import re
from reproduce import REGIME_TO_STAGE, render
import json
from pathlib import Path

cases = json.loads(Path('fixtures/public_cases.json').read_text())
for name, case in cases.items():
    stage = REGIME_TO_STAGE[case['regime']]
    text = render(case)
    if stage == 'deep_on':
        assert 'pair deepmd scale * * v_ONE' in text
        continue

    coeff = {}
    for line in text.splitlines():
        fields = line.split()
        if fields[:1] == ['pair_coeff']:
            if 'lj/cut/soft' in fields:
                offset = fields.index('lj/cut/soft') + 1
            else:
                offset = 3
            coeff[(int(fields[1]), int(fields[2]))] = float(fields[offset])

    variables = {}
    pending = {}
    for line in text.splitlines():
        fields = line.split()
        if fields[:1] "'!= ['"'variable'] or fields[2:3] "'!= ['"'equal']:
            continue
        name_var, value = fields[1], fields[3]
        try:
            variables[name_var] = float(value)
        except ValueError:
            match = re.fullmatch(r'-\\"'$'"\\{(["'^}]+)'"\\}', value)
            if match:
                pending[name_var] = match.group(1)
    for var, source in pending.items():
        variables[var] = -variables[source]

    compute = next(line for line in text.splitlines() if line.startswith('compute         e_diff'))
    tokens = compute.split()
    terms = []
    cursor = 5
    while cursor < len(tokens):
        assert tokens[cursor:cursor + 3] == ['pair', 'lj/cut/soft', 'epsilon']
        i, j, variable = tokens[cursor + 3:cursor + 6]
        terms.append((i, j, variables[variable.removeprefix('v_')]))
        cursor += 6

    sign = 1 if stage == 'soft_on' else -1
    if terms[0][:2] == ('*', '*'):
        assert len(terms) == 1
        assert all(terms[0][2] == sign * value for value in coeff.values())
    else:
        observed = {(int(i), int(j)): value for i, j, value in terms}
        assert observed == {pair: sign * value for pair, value in coeff.items()}
    assert '/v_LAMBDA' not in text and '/v_INV_LAMBDA' not in text
    print(f'{name}: {len(coeff)} coefficients mapped with sign {sign:+d}')
